<?php
require __DIR__.'/../../app/bootstrap.php'; require __DIR__.'/../../app/online_fulfillment.php';
header('Content-Type: application/json; charset=utf-8');
function api_out(int $code,array $data): never {http_response_code($code);echo json_encode($data,JSON_UNESCAPED_UNICODE);exit;}
if($_SERVER['REQUEST_METHOD']!=='POST')api_out(405,['ok'=>false,'error'=>'POST only']);
$key=online_order_api_key();if(strlen($key)<32)api_out(503,['ok'=>false,'error'=>'Order API is disabled until a 32+ character key is configured.']);
$auth=$_SERVER['HTTP_AUTHORIZATION']??($_SERVER['REDIRECT_HTTP_AUTHORIZATION']??'');$given=preg_match('/^Bearer\s+(.+)$/i',$auth,$m)?trim($m[1]):'';if($given===''||!hash_equals($key,$given))api_out(401,['ok'=>false,'error'=>'Unauthorized']);
$body=json_decode(file_get_contents('php://input'),true);if(!is_array($body))api_out(400,['ok'=>false,'error'=>'Invalid JSON']);
try{$source=strtoupper(trim((string)($body['source']??'API')));if(!in_array($source,['WEBSITE','MARKETPLACE','API'],true))$source='API';$external=trim((string)($body['external_order_id']??''));if($external!==''){$st=db()->prepare('SELECT id,order_no,status FROM online_orders WHERE source=? AND external_order_id=? LIMIT 1');$st->execute([$source,$external]);if($ex=$st->fetch())api_out(200,['ok'=>true,'duplicate'=>true,'order'=>$ex]);}
 $items=[];foreach(($body['items']??[]) as $it){$sku=trim((string)($it['sku']??''));$qty=(float)($it['quantity']??0);$st=db()->prepare('SELECT id FROM products WHERE sku=? AND active=1 LIMIT 1');$st->execute([$sku]);$pid=(int)$st->fetchColumn();if(!$pid)throw new Exception('Unknown SKU: '.$sku);$items[]=['product_id'=>$pid,'quantity'=>$qty];}if(!$items)throw new Exception('At least one item is required.');
 $locs=[];$locCode=trim((string)($body['location_code']??''));$warehouse=trim((string)($body['warehouse']??''));if($locCode!==''){$st=db()->prepare('SELECT id FROM locations WHERE code=? AND active=1 AND online_fulfillment_enabled=1');$st->execute([$locCode]);$lid=(int)$st->fetchColumn();if(!$lid)throw new Exception('Unknown or disabled fulfilment location.');$locs=[$lid];}elseif($warehouse!==''){$st=db()->prepare('SELECT id FROM locations WHERE warehouse=? AND active=1 AND online_fulfillment_enabled=1 ORDER BY id');$st->execute([$warehouse]);$locs=array_map('intval',array_column($st->fetchAll(),'id'));if(!$locs)throw new Exception('Unknown or disabled fulfilment warehouse.');}else{$whs=db()->query("SELECT DISTINCT warehouse FROM locations WHERE active=1 AND online_fulfillment_enabled=1 AND COALESCE(warehouse,'')<>'' ORDER BY warehouse")->fetchAll();if(count($whs)>1)throw new Exception('Multiple fulfilment warehouses are enabled. Send warehouse or location_code.');$locs=array_map('intval',array_column(db()->query('SELECT id FROM locations WHERE active=1 AND online_fulfillment_enabled=1 ORDER BY id')->fetchAll(),'id'));}
 db()->beginTransaction();$oid=online_create_and_reserve(['order_no'=>$body['order_no']??'','source'=>$source,'external_order_id'=>$external,'customer_name'=>$body['customer_name']??'','customer_mobile'=>$body['customer_mobile']??'','shipping_address'=>$body['shipping_address']??'','order_amount'=>$body['order_amount']??0,'payment_status'=>$body['payment_status']??'PENDING','notes'=>$body['notes']??'API order'],$items,$locs,null);db()->commit();audit('ONLINE_ORDER_API_CREATE','online_order',$oid,['source'=>$source]);publish_event('ONLINE_ORDER_NEW','Online order allocated',online_order_number($oid).' · API stock reserved',['super_admin'],'online_order',$oid,null);publish_scoped_event('ONLINE_ORDER_PICK','Online order ready to pick',online_order_number($oid).' · scan rack then item',['manager','godown'],'online_order',$oid);api_out(201,['ok'=>true,'order_id'=>$oid,'order_no'=>online_order_number($oid),'status'=>'ALLOCATED']);
}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();
 // Database faults are logged, never shown to the caller. Business messages (unknown SKU, no stock...) stay as they are.
 if($e instanceof PDOException){
  // Two requests with the same website order id at the same moment: the loser gets the normal duplicate answer.
  if((int)($e->errorInfo[1]??0)===1062&&($external??'')!==''&&strpos($e->getMessage(),'uq_online_source_external')!==false){$st=db()->prepare('SELECT id,order_no,status FROM online_orders WHERE source=? AND external_order_id=? LIMIT 1');$st->execute([$source,$external]);if($ex=$st->fetch())api_out(200,['ok'=>true,'duplicate'=>true,'order'=>$ex]);}
  error_log('order_create: '.$e->getMessage());api_out(500,['ok'=>false,'error'=>'The order could not be saved. Please retry.']);
 }
 api_out(422,['ok'=>false,'error'=>$e->getMessage()]);}
